<template>
  <NConfigProvider :locale="zhCN" :date-locale="dateZhCN">
  <section class="risk-page" aria-label="风险排查" data-v2-inline-feedback>
    <header class="risk-toolbar" data-v2-navigation>
      <NButton v-if="detail||editor" :disabled="busy||!!pendingPublication" @click="back"><ArrowLeft :size="16" />{{viewLabel}}</NButton>
      <NButton v-else-if="legacy" :disabled="busy" aria-label="返回" @click="navigate(scope?'/?entry=risk_inspection':'/?entry=special')"><ArrowLeft :size="16" />返回</NButton>
      <strong>{{editor==='publish'?'发布风险排查':editor==='base'?'基础模板库':editor==='choose'?'选择基础模板':editor==='history'?'历史模板库':detail?.name||'风险排查'}}</strong>
      <div class="risk-tools"><NButton v-if="!libraryMode" :disabled="busy||unsaved||!!pendingPublication" :loading="loading" title="刷新" aria-label="刷新" @click="reload"><RefreshCw :size="16" /></NButton><template v-if="isManager&&activeView==='published'&&!detail&&!editor"><NButton :disabled="busy||loading" @click="openEditor('base')"><Settings2 :size="16" />基础模板</NButton><NButton :disabled="busy||loading" @click="openEditor('history')"><Library :size="16" />历史模板库</NButton><NButton type="primary" :disabled="busy||loading" @click="openEditor('publish')"><Plus :size="16" />发布排查</NButton></template></div>
    </header>
    <NTabs v-if="!detail&&!editor" :value="activeView" type="segment" aria-label="排查工作区" role="tablist" data-v2-navigation @update:value="changeView"><NTab v-if="isManager" name="published" role="tab" :aria-selected="activeView==='published'" tabindex="0" @keydown.enter.prevent="changeView('published')" @keydown.space.prevent="changeView('published')">发布管理</NTab><NTab name="mine" role="tab" :aria-selected="activeView==='mine'" tabindex="0" @keydown.enter.prevent="changeView('mine')" @keydown.space.prevent="changeView('mine')">我的排查任务</NTab><NTab name="review" role="tab" :aria-selected="activeView==='review'" tabindex="0" @keydown.enter.prevent="changeView('review')" @keydown.space.prevent="changeView('review')">我的审核任务</NTab></NTabs>
    <NAlert v-if="error&&!confirmation&&!fieldEditor&&!feedbackOpen&&!pendingPublication" type="error" :bordered="false" role="alert">{{error}} <NButton v-if="detail" text :disabled="busy" @click="readLatest">重新读取，保留填写</NButton></NAlert>
    <NAlert v-if="message&&!feedbackOpen" type="info" :bordered="false" role="status">{{message}}</NAlert>
    <NSpin :show="loading">
      <RiskInspectionTemplateLibrary v-if="libraryMode" :key="editor" ref="historyLibrary" :kind="editor==='history'?'history':'base'" :selecting="editor==='choose'" :can-edit-library="canEditTemplate" @reuse="reuseHistory" />
      <template v-else-if="editor==='template'&&template">
        <div class="risk-section-heading"><div><strong>字段配置</strong><span>{{inputFields.length}} 个填写字段</span></div><NButton v-if="canEditTemplate" :disabled="busy||template.fields.length>=80" @click="editField()"><Plus :size="16" />添加字段</NButton></div>
        <NAlert v-if="template.fields.some((field:Dict)=>field.unsupported)" type="warning" :bordered="false">存在关联、公式或其它不支持复制的字段，调整后才可发布。</NAlert>
        <RiskInspectionSheet :fields="template.fields" schema :can-edit="canEditTemplate" :disabled="busy" @edit="editField" @remove-field="field=>ask('delete_field',field)" @required-change="changeRequired" />
        <p class="risk-note">必填字段在排查人提交时校验，发布预填和保存草稿可留空。修改仅用于后续发布，不改变已发布任务；删除字段会移除基础模板对应列的数据。</p>
      </template>
      <form v-else-if="editor==='publish'&&template" class="risk-publish" @submit.prevent="ask('publish')">
        <div class="risk-section-heading"><div><strong>发布信息</strong><NTag size="small" :bordered="false">{{publish.history_template_id?'历史模板：':'基础模板：'}}{{template.name}} · V{{template.revision}}</NTag></div><div class="risk-tools"><NButton :disabled="publicationLocked" @click="openEditor('publish')">更换基础模板</NButton><NButton :disabled="publicationLocked" @click="openEditor('history')"><Library :size="16" />选择历史模板</NButton></div></div>
        <NAlert v-if="template.legacy" type="warning" :bordered="false">原任务未保留原始预填内容，已仅带入字段和事项标题，请核对补充。</NAlert>
        <div class="risk-fields"><label><span>排查表名 *</span><NInput v-model:value="publish.name" :disabled="publicationLocked" :maxlength="120" placeholder="例如：10月电气设备专项排查" :input-props="{'aria-label':'排查表名'}" /></label><label><span>反馈截止时间 *</span><NDatePicker :to="true" v-model:value="publish.deadline" :disabled="publicationLocked" type="datetime" clearable :input-props="{'aria-label':'反馈截止时间'}" /></label><label><span>审核人 *</span><NSelect :to="true" v-model:value="publish.reviewer_ids" :disabled="publicationLocked" multiple filterable :max-tag-count="2" :options="peopleOptions" placeholder="选择审核人" aria-label="审核人" /></label><label><span>接收人员 *</span><NSelect :to="true" v-model:value="selectedPeople" :disabled="publicationLocked" multiple filterable :max-tag-count="2" :options="peopleOptions" placeholder="搜索姓名或工号" aria-label="接收人员" /></label></div>
        <details v-if="selectedRows.length" class="risk-recipients" :open="publish.people.some((p:Dict)=>!p.scopes.length)"><summary><span>接收人员 {{selectedRows.length}} 人</span><span class="risk-scope-summary">{{recipientSummary}}</span><span>人员 / 楼栋</span></summary><div class="risk-recipient-editor"><div v-for="person in selectedRows" :key="person.id"><span>{{person.name}}<small>{{person.employee_no}}</small></span><NSelect :to="true" :disabled="publicationLocked" multiple :max-tag-count="2" :value="publish.people.find((p:Dict)=>p.id===person.id)?.scopes||[]" :options="riskRecipientScopes(person).map((s:string)=>({value:s,label:scopeLabel(s)}))" placeholder="请选择楼栋" :aria-label="person.name+'的接收楼栋'" @update:value="s=>setScopes(person.id,s)" /></div></div></details>
        <div class="risk-fields"><label class="wide"><span>接收经理 *</span><NSelect :to="true" v-model:value="publish.manager_ids" :disabled="publicationLocked" multiple filterable :options="managerOptions" placeholder="选择接收最终结果的经理" aria-label="接收经理" /></label></div>
        <NAlert v-if="pendingPublication&&!busy" type="warning" :bordered="false" role="status" class="risk-publish-recovery"><strong>发布结果尚未确认，原内容已锁定保留。</strong><p v-if="error">{{error}}</p><div class="risk-tools"><NButton :disabled="busy" @click="checkPublication">核验本次发布</NButton><NButton :disabled="busy" @click="publishNow">按原内容重试</NButton></div></NAlert>
        <div class="risk-section-heading"><div><strong>排查事项</strong><span>{{publish.items.length}} 行 · {{inputFields.length}} 个填写字段</span></div><NButton :disabled="publicationLocked||publish.items.length>=100" @click="publish.items.push({title:'',values:{}})"><Plus :size="16" />添加事项</NButton></div>
        <RiskInspectionSheet :fields="template.fields" v-model:items="publish.items" :disabled="publicationLocked" />
        <footer class="risk-footer"><div><strong>{{selectedPeople.length}} 人 · {{assignmentCount}} 项个人任务</strong><span v-if="publishProblems.length&&!pendingPublication" class="risk-publish-missing">待补充：{{publishProblems.slice(0,3).join('；')}}{{publishProblems.length>3?' 等'+publishProblems.length+'项':''}}</span><span v-else class="risk-note">{{pendingPublication?'待核验本次发布':'每位接收人按楼栋独立反馈，任一审核人通过即完成审核'}}</span></div><NButton attr-type="submit" type="primary" :disabled="publicationLocked||!publishValid">确认发布</NButton></footer>
      </form>
      <div v-else-if="editor" class="risk-template-empty"><NEmpty v-if="!loading" description="模板或人员目录未完整读取，已阻止发布"><template #extra><NButton :disabled="busy" @click="reload">重新读取</NButton></template></NEmpty></div>
      <template v-else-if="detail">
        <div class="risk-role-view"><NTag :bordered="false" type="info">{{viewLabel}}</NTag><div class="risk-tools"><NButton v-if="activeView!=='mine'&&hasOwnTask" size="small" :disabled="busy" @click="changeView('mine',detail.id)">切换到我的排查</NButton><NButton v-if="activeView!=='review'&&detail.is_reviewer" size="small" :disabled="busy" @click="changeView('review',detail.id)">进入审核任务</NButton></div></div>
        <div class="risk-toolbar risk-summary"><span>{{detail.owner}}发布 · 审核人 {{riskReviewerNames(detail)}} · 截止 {{date(detail.deadline)}}</span><div class="risk-tools"><NButton v-if="detail.can_manage_release&&detail.status==='active'" size="small" :disabled="busy" @click="openReviewer">更换审核人</NButton><a v-if="detail.url" :href="detail.url" target="_blank" rel="noopener noreferrer">查看结果表 <ExternalLink :size="14" /></a><NButton v-if="activeView==='published'&&detail.can_delete_release" size="small" quaternary type="error" :disabled="busy" @click="ask('delete_release',detail)"><Trash2 :size="15" />删除任务</NButton></div></div>
        <p v-if="detail.final_managers?.length" class="risk-final-push">接收经理：{{detail.final_managers.map((manager:Dict)=>manager.name).join('、')}}</p>
        <NAlert v-if="detail.status!=='active'" type="warning" :bordered="false">{{failedJobs.some((job:Dict)=>job.kind==='publish')?'发布尚未完成，暂不能领取或填写。已创建的结果表会保留，请查看原因并重试原任务，不要重新发布。':'正在创建排查表并登记链接，完成后自动发送邀请。请勿重复发布。'}}</NAlert>
        <div v-if="incompleteJobs.length" class="risk-sync"><span>{{failedJobs.length?'部分云端操作未完成':'云端处理中'}} · {{incompleteJobs.length}} 项</span><NButton v-if="detail.can_manage_release&&failedJobs.some((j:Dict)=>j.status==='failed')" size="small" :disabled="busy" @click="ask('retry')">重试未完成操作</NButton><details v-if="failedJobs.length"><summary>查看原因</summary><p v-for="job in failedJobs" :key="job.id">{{jobLabel(job.kind)}}：{{job.error}}</p></details></div>
        <div v-if="activeView==='mine'&&detail.can_claim" class="risk-claim"><span>需要本人参与时，可领取一份独立任务。</span><NSelect :to="true" v-model:value="claimScope" :disabled="busy" :options="detail.claim_scopes.map((s:string)=>({value:s,label:scopeLabel(s)}))" aria-label="本人领取楼栋" /><NButton type="primary" :disabled="busy||!claimScope" @click="ask('claim')">领取本人任务</NButton></div>
        <RiskInspectionTable v-if="feedbackDetail?.people.length" :key="detail.id+':'+activeView" :detail="feedbackDetail!" :view="activeView" :busy="busy" @open="openFeedback" />
        <NEmpty v-else-if="detail.status==='active'" :description="activeView==='review'?'你不是本次排查的当前审核人':detail.can_claim?'尚未领取本人任务':'本次排查没有分配给本人'" />
        <NDrawer :show="feedbackOpen" placement="right" width="min(760px, 100vw)" :mask-closable="!busy" :close-on-esc="!busy" @update:show="value=>{if(!value)closeFeedback()}">
          <NDrawerContent :title="person?person.name+' · '+scopeLabel(focusedItems[0]?.scope||person.scope):'排查反馈'" :closable="!busy" class="risk-feedback-drawer" data-v2-inline-feedback>
          <main v-if="person" ref="feedbackForm" class="risk-feedback">
            <NAlert v-if="error&&!confirmation" type="error" :bordered="false" role="alert">{{error}} <NButton text :disabled="busy" @click="readLatest">重新读取，保留填写</NButton></NAlert>
            <NAlert v-if="message" type="info" :bordered="false" role="status">{{message}}</NAlert>
            <header class="risk-toolbar"><NTag :bordered="false">{{personProgress(person)}}</NTag><NButton v-if="activeView==='published'&&detail.is_manager&&!person.revoked" type="error" size="small" quaternary :disabled="busy" @click="ask('revoke_person')">撤销该人员</NButton></header>
            <article v-for="item in focusedItems" :key="item.id" class="risk-response" :class="{revoked:item.status==='revoked'}">
              <header><strong>{{item.title}}</strong><NTag size="small" :bordered="false">{{scopeLabel(item.scope||person.scope)}}</NTag><NTag :type="item.status==='approved'?'success':item.status==='returned'?'warning':'default'" size="small">{{statusName(item.status)}}</NTag><NButton v-if="activeView==='published'&&detail.is_manager&&!person.revoked&&item.status!=='revoked'" size="small" quaternary type="error" :disabled="busy" @click="ask('revoke_item',item)">撤销事项</NButton></header>
              <p v-if="item.reason" class="risk-note">{{item.status==='revoked'?'撤销原因':item.reviewed_by||'管理员'}}：{{item.reason}}</p>
              <NAlert v-if="editable(item)&&validationItem===item.id&&missingFields(item).length" type="warning" :bordered="false" role="alert" class="risk-missing-summary"><strong>还有 {{missingFields(item).length}} 项必填信息待补充</strong><div class="risk-tools"><NButton v-for="field in missingFields(item)" :key="field.key" text @click="focusField(field.key)">{{field.field_name}}</NButton></div></NAlert>
              <RiskInspectionFields :fields="detail.fields" :values="editable(item)?drafts[item.id]||item.values:item.values" :system-values="item.system_values" :files="item.files" :disabled="!editable(item)||busy" :invalid-fields="validationItem===item.id?missingFields(item).map((field:Dict)=>field.key):[]" @update:values="v=>drafts[item.id]=v" @files="(field,files)=>uploadFiles(item,field,files)" />
              <details v-if="drafts[item.id]&&!editable(item)" class="risk-local-draft"><summary>本地未提交内容（当前事项已变更）</summary><RiskInspectionFields :fields="detail.fields" :values="drafts[item.id]" :system-values="item.system_values" :files="item.files" disabled /><NButton size="small" :disabled="busy" @click="discardDraft(item.id)">放弃这份本地填写</NButton></details>
              <footer><small>{{item.submitted_at?'提交于 '+date(item.submitted_at*1000):'尚未提交'}}{{item.reviewed_at?' · 审核于 '+date(item.reviewed_at*1000):''}}</small><div class="risk-tools"><template v-if="editable(item)"><NButton :disabled="busy" @click="act('save',item)">保存草稿</NButton><NButton type="primary" :disabled="busy" @click="ask('submit',item)">提交审核</NButton></template><template v-if="activeView==='review'&&detail.is_reviewer&&detail.status==='active'&&item.status==='submitted'&&!person.revoked"><NButton :disabled="busy" @click="ask('return',item)">退回修改</NButton><NButton type="primary" :disabled="busy" @click="ask('approve',item)">审核通过</NButton></template></div></footer>
            </article>
          </main>
          <NEmpty v-else description="当前人员反馈已不在可访问范围，请关闭后重新选择。" />
          </NDrawerContent>
        </NDrawer>
        <details class="risk-audit"><summary>操作记录</summary><p v-for="(row,index) in detail.audit" :key="index">{{date(row.at*1000)}} · {{auditName(row)}} · {{actionName(row.action)}}</p></details>
      </template>
      <template v-else>
        <div class="risk-list-controls"><NInput v-model:value="taskSearch" clearable placeholder="搜索本页任务或审核人" :input-props="{'aria-label':'搜索排查任务'}"><template #prefix><Search :size="16" /></template></NInput><NSelect :to="true" v-model:value="taskState" clearable :options="taskStateOptions" placeholder="全部状态" aria-label="排查任务状态" /><span>本页 {{filteredTasks.length}} / {{list.length}} 项</span></div>
        <div class="risk-task-list"><NDataTable :columns="taskColumns" :data="filteredTasks" :row-key="task=>task.id" :row-props="taskRowProps" :scroll-x="1050" size="small" :bordered="false" striped><template #empty><NEmpty :description="taskSearch||taskState?'本页没有符合条件的任务':'暂无分配的风险排查'"><template v-if="taskSearch||taskState" #extra><NButton @click="taskSearch='';taskState=null">清除筛选</NButton></template></NEmpty></template></NDataTable></div>
        <div class="risk-mobile-tasks"><article v-for="task in filteredTasks" :key="task.id" class="risk-mobile-task" v-bind="taskRowProps(task)"><header><NButton text class="risk-task-name" :disabled="busy" data-v2-navigation @click="openTask(task.id)">{{task.name}}</NButton><NTag size="small" :bordered="false" :type="task.total>0&&task.approved===task.total?'success':'default'">{{taskStatus(task)}}</NTag></header><dl><div><dt>反馈 / 总项数</dt><dd>{{task.submitted}} / {{task.total}}</dd></div><div><dt>已通过</dt><dd>{{task.approved}}</dd></div><div><dt>人员</dt><dd>{{task.people_count}} 人</dd></div></dl><p :class="{overdue:task.deadline<Date.now()&&task.approved<task.total}">截止 {{date(task.deadline)}} · {{riskReviewerNames(task)}}审核</p><footer><NButton v-if="activeView==='published'&&task.can_delete_release" quaternary type="error" :disabled="busy" :aria-label="'删除任务：'+task.name" @click="ask('delete_release',task)"><Trash2 :size="15" />删除</NButton><NButton :disabled="busy" type="primary" secondary data-v2-navigation @click="openTask(task.id)">{{taskAction(task)}}</NButton></footer></article><NEmpty v-if="!filteredTasks.length" :description="taskSearch||taskState?'本页没有符合条件的任务':'暂无分配的风险排查'"><template v-if="taskSearch||taskState" #extra><NButton @click="taskSearch='';taskState=null">清除筛选</NButton></template></NEmpty></div>
        <footer class="risk-list-footer"><span>共 {{total}} 个排查任务</span><NPagination v-if="total>20" :page="page" :page-count="Math.ceil(total/20)" :page-slot="5" @update:page="changePage" /></footer>
      </template>
    </NSpin>
    <NModal :show="!!discard" preset="dialog" title="内容尚未保存" :content="discard?.message" type="warning" positive-text="放弃修改" negative-text="继续填写" :mask-closable="false" @positive-click="discardChanges" @negative-click="discard=null" @update:show="show=>{if(!show)discard=null}" />
    <NModal :show="!!fieldEditor" preset="card" title="模板字段" class="risk-modal" :mask-closable="false" :closable="!busy" :close-on-esc="!busy" @update:show="v=>{if(!v)closeFieldEditor()}"><NAlert v-if="error&&!confirmation" type="error" :bordered="false" role="alert">{{error}}</NAlert><div v-if="fieldEditor" class="risk-fields"><label><span>字段名称</span><NInput v-model:value="fieldEditor.field_name" :disabled="busy" :maxlength="80" :input-props="{'aria-label':'字段名称'}" /></label><label><span>字段类型</span><NSelect :to="true" v-model:value="fieldEditor.type" :options="typeOptions" :disabled="busy||fieldEditor.is_primary" aria-label="字段类型" /></label><label><span>填写方式</span><NSelect :to="true" v-model:value="fieldEditor.role" :disabled="busy" :options="roleOptions" aria-label="填写方式" /></label><label><span>填写要求</span><div v-if="fieldEditor.role==='input'" class="risk-required"><NSwitch v-model:value="fieldEditor.required" :disabled="busy" aria-label="字段是否必填" /><span>{{fieldEditor.required?'必填':'不必填'}}</span></div><small v-else>由系统自动填写，无需设置</small></label><label v-if="[3,4].includes(fieldEditor.type)" class="wide"><span>选项，每行一个</span><NInput v-model:value="fieldEditor.optionsText" :disabled="busy" type="textarea" :autosize="{minRows:3,maxRows:8}" /></label></div><template #footer><div class="risk-tools"><NButton :disabled="busy" @click="closeFieldEditor">取消</NButton><NButton type="primary" :disabled="busy||!fieldEditor?.field_name?.trim()" @click="ask('save_field')">保存字段</NButton></div></template></NModal>
    <NModal :show="!!confirmation" preset="card" :title="confirmTitle" class="risk-modal risk-confirm" :mask-closable="false" :close-on-esc="!busy" :closable="!busy" @update:show="v=>{if(!v&&!busy)confirmation=null}">
      <NAlert v-if="error" type="error" :bordered="false" role="alert">{{error}} <NButton v-if="detail&&confirmation?.action!=='delete_release'" text :disabled="busy" @click="readLatest">重新读取，保留填写</NButton></NAlert>
      <p>{{confirmation?.action==='delete_release'?deleteDescription:confirmText}}</p>
      <dl v-if="confirmation?.action==='publish'" class="risk-confirm-summary"><dt>排查表名</dt><dd>{{publish.name}}</dd><dt>反馈截止</dt><dd>{{date(publish.deadline)}}</dd><dt>审核人</dt><dd>{{people.filter((person:Dict)=>publish.reviewer_ids.includes(person.id)).map((person:Dict)=>person.name).join('、')}}</dd><dt>接收经理</dt><dd>{{people.filter((person:Dict)=>publish.manager_ids.includes(person.id)).map((person:Dict)=>person.name).join('、')}}</dd><dt>任务分配</dt><dd>{{selectedPeople.length}} 人 · {{assignmentCount}} 项个人任务 · {{recipientSummary}}</dd></dl>
      <NSelect :to="true" v-if="confirmation?.action==='reviewer'" v-model:value="newReviewers" :options="peopleOptions" :disabled="busy" multiple filterable placeholder="选择新审核人" aria-label="新审核人" />
      <NInput v-if="needsReason" v-model:value="reason" :disabled="busy" type="textarea" :maxlength="2000" :autosize="{minRows:2,maxRows:4}" placeholder="请填写原因" />
      <template #footer><div class="risk-tools"><NButton :disabled="busy" @click="confirmation=null">取消</NButton><NButton :type="confirmation?.action==='delete_release'?'error':'primary'" :loading="busy" :disabled="busy||needsReason&&!reason.trim()||confirmation?.action==='reviewer'&&!!reviewerIssue(newReviewers,people)" @click="confirm">{{confirmation?.action==='delete_release'?'确认删除':'确认'}}</NButton></div></template>
    </NModal>
  </section>
  </NConfigProvider>
</template>
<script setup lang="ts">
import {computed,h,nextTick,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import {NAlert,NButton,NConfigProvider,NDataTable,NDatePicker,NDrawer,NDrawerContent,NEmpty,NInput,NModal,NPagination,NSelect,NSpin,NSwitch,NTab,NTabs,NTag,zhCN,dateZhCN,type DataTableColumns} from 'naive-ui';
import {ArrowLeft,ExternalLink,Library,Plus,RefreshCw,Search,Settings2,Trash2} from 'lucide-vue-next';
import {ApiError,requestJson,type Dict} from '../api/client';
import {navigate,registerNavigationGuard} from '../navigation';
import {activateCard} from '../workspace-v2/cardActivation';
import RiskInspectionFields from './RiskInspectionFields.vue';
import RiskInspectionTemplateLibrary from './RiskInspectionTemplateLibrary.vue';
import RiskInspectionTable from './RiskInspectionTable.vue';
import RiskInspectionSheet from './RiskInspectionSheet.vue';
import {missingRiskFields,publicationIssues,reviewerIssue,riskAssignedScopes,riskFieldRole,riskFinalScopes,riskRecipientScope,riskRecipientScopes,riskReviewerIds,riskReviewerNames,riskRoles,riskSystemField,riskTaskPriority,riskTaskView,riskTypeOptions,type RiskTaskView} from './riskInspectionUi';
const props=defineProps<{releaseId?:string;scope?:string;view?:string}>();
