async function reload(){
 if(libraryMode.value)return;
 if(busy.value||dirty.value)return;read?.abort();const abort=new AbortController();read=abort;loading.value=true;error.value='';
 try{if(editor.value){const mode=editor.value,path=mode==='publish'&&publish.base_template_id?'/base-templates/'+publish.base_template_id:mode==='publish'&&publish.history_template_id?'/templates/'+publish.history_template_id:'/template';template.value=null;const [data,directory]=await Promise.all([requestJson(root+path,{signal:abort.signal,cache:'no-store',timeoutMs:60000}),mode==='publish'?requestJson(root+'/people',{signal:abort.signal,cache:'no-store'}):Promise.resolve(null)]);if(!Array.isArray(data.fields)||!data.fields.length||!data.version||directory&&!Array.isArray(directory.items))throw new Error('模板或人员目录返回不完整，暂不能发布，请重新读取。');if(!abort.signal.aborted){template.value=data;if(directory){people.value=directory.items;if(!publish.reviewer_ids.length)publish.reviewer_ids=directory.self_id?[directory.self_id]:[];}}}
 else if(detail.value){const data=await requestJson(root+'/'+detail.value.id,{signal:abort.signal,cache:'no-store'});if(!abort.signal.aborted)applyDetail(data);}
 else {const data=await requestJson(root+'?page='+page.value+'&view='+activeView.value+(props.scope&&isManager.value&&activeView.value==='published'?'&scope='+encodeURIComponent(props.scope):''),{signal:abort.signal,cache:'no-store'});if(!abort.signal.aborted){list.value=data.items;total.value=data.total;isManager.value=data.is_manager;canEditTemplate.value=data.can_edit_template;activeView.value=riskTaskView(data.view)||(data.is_manager||activeView.value==='review'?activeView.value:'mine');}}}
 catch(e:any){if(!abort.signal.aborted)error.value=e.message;}finally{if(read===abort){loading.value=false;read=undefined;}}
}
async function openTask(id:string,fromRoute=false){if(busy.value)return;read?.abort();const abort=new AbortController();read=abort;loading.value=true;error.value='';try{const d=await requestJson(root+'/'+encodeURIComponent(id),{signal:abort.signal,cache:'no-store'});if(!abort.signal.aborted){validateDetail(d);if(fromRoute&&!riskTaskView(new URLSearchParams(window.location.search).get('view')))activeView.value=d.people.some((p:Dict)=>p.id===d.self_id)?'mine':d.is_reviewer?'review':isManager.value?'published':'mine';applyDetail(d);if(!fromRoute)navigate(taskUrl(activeView.value,id));}}catch(e:any){if(!abort.signal.aborted)error.value=e.message;}finally{if(read===abort){read=undefined;loading.value=false;}}}
