function resetPublication(){selectedPeople.value=[];Object.assign(publish,{id:Array.from(crypto.getRandomValues(new Uint8Array(16)),v=>v.toString(16).padStart(2,'0')).join(''),name:'',deadline:null,reviewer_ids:[],manager_ids:[],people:[],items:[{title:'',values:{}}],history_template_id:'',base_template_id:''});}
function openEditor(mode:string){const proceed=()=>{read?.abort();resetPublication();template.value=null;editor.value=mode==='publish'?'choose':mode;message.value='';error.value='';};if(leaveAllowed(proceed))proceed();}
async function reuseHistory(data:Dict){beginWrite();error.value='';try{const directory=await requestJson(root+'/people',{cache:'no-store'});if(!Array.isArray(directory.items))throw new Error('人员目录未完整返回，请重试。');people.value=directory.items;resetPublication();template.value=data;Object.assign(publish,{name:data.name,reviewer_ids:directory.self_id?[directory.self_id]:[],items:data.items?.length?structuredClone(data.items):[{title:'',values:{}}],history_template_id:data.kind==='base'?'':data.id,base_template_id:data.kind==='base'?data.id:''});editor.value='publish';message.value='已带入所选模板；请确认人员、审核人及截止时间。';}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
function back(){const proceed=()=>{resetPublication();feedbackOpen.value=false;detail.value=null;editor.value='';fieldEditor.value=null;drafts.value={};message.value='';navigate(taskUrl(activeView.value));void reload();};if(leaveAllowed(proceed))proceed();}
function changeView(value:string,id=''){const view=riskTaskView(value);if(!view||view===activeView.value)return;const proceed=()=>{activeView.value=view;if(id!==detail.value?.id)detail.value=null;feedbackOpen.value=false;drafts.value={};editor.value='';page.value=1;taskSearch.value='';taskState.value=null;message.value='';navigate(taskUrl(view,id));if(id)void openTask(id,true);else void reload();};if(leaveAllowed(proceed))proceed();}
function routeChanged(){const view=riskTaskView(props.view||null)||(isManager.value?'published':'mine'),id=props.releaseId||'';if(view===activeView.value&&id===(detail.value?.id||''))return;activeView.value=view;detail.value=null;feedbackOpen.value=false;drafts.value={};editor.value='';fieldEditor.value=null;message.value='';if(id)void openTask(id,true);else void reload();}
