async function act(action:string,item?:Dict,version=person.value?.version){
 if(busy.value||!detail.value||!person.value||['approve','return'].includes(action)&&(activeView.value!=='review'||!detail.value.is_reviewer)||['save','submit'].includes(action)&&(!item||!editable(item)))return;if(action==='submit'&&item&&!feedbackComplete(item)){confirmation.value=null;return;}beginWrite();error.value='';message.value='';
