  if(!e.status||e.status>=500){try{await requestJson(root+'/'+task.id,{cache:'no-store'});}catch(check:any){if(check.status===410)deleted=true;}}
  if(!deleted)error.value=e.message;
 }finally{busy.value=false;}
 if(!deleted)return;
 confirmation.value=null;detail.value=null;feedbackOpen.value=false;drafts.value={};
 if(list.value.length===1&&page.value>1)page.value--;
 await reload();message.value='排查任务已删除；已有反馈、历史模板和多维结果表保留。';
}
async function confirm(){
 const c=confirmation.value;if(!c||busy.value)return;
 if(c.action==='delete_release'){await deleteTask(c.item);return;}
 if(c.action==='publish'){await publishNow();return;}
 if(c.action==='retry'){await retry();return;}
 if(c.action==='claim'){beginWrite();error.value='';try{applyDetail(await requestJson(root+'/'+detail.value!.id+'/claim',{method:'POST',body:JSON.stringify({scope:claimScope.value})}));activeView.value='mine';personId.value=detail.value!.self_id;const first=person.value?.items.find((item:Dict)=>['pending','returned'].includes(item.status));if(first){focusedItemId.value=first.id;feedbackOpen.value=true;}confirmation.value=null;message.value='本人任务已领取，可填写并提交审核。';}catch(e:any){error.value=e.message;}finally{busy.value=false;}return;}
 if(c.action==='reviewer'){if(reviewerIssue(newReviewers.value,people.value))return;beginWrite();error.value='';try{applyDetail(await requestJson(root+'/'+detail.value!.id+'/reviewer',{method:'POST',body:JSON.stringify({reviewer_ids:newReviewers.value,version:c.version})}));confirmation.value=null;message.value='审核人已更换，待审核事项将通知新审核人。';}catch(e:any){error.value=e.message;}finally{busy.value=false;}return;}
 if(!['save_field','delete_field'].includes(c.action)){await act(c.action,c.item,c.version);return;}
 beginWrite();error.value='';
 try{const f=c.action==='delete_field'?c.item:c.item||fieldEditor.value;const originalOptions=(f.property?.options||[]).map((option:Dict)=>option.name);const options=c.item||f.optionsText===originalOptions.join('\n')?originalOptions:(f.optionsText||'').split('\n').map((s:string)=>s.trim()).filter(Boolean);template.value=await requestJson(root+'/template',{method:'POST',body:JSON.stringify({action:c.action==='delete_field'?'delete':f.key?'update':'add',version:template.value?.version,field_id:f.key,field_name:f.field_name,type:f.type,role:f.role,required:f.required,options,confirmed:true}),timeoutMs:60000});fieldEditor.value=null;message.value='模板已保存，已发布任务不受影响。';
 confirmation.value=null;
 }catch(e:any){error.value=e.message;}finally{busy.value=false;}
}
function publicationAccepted(data:Dict){applyDetail(data);pendingPublication.value=null;confirmation.value=null;editor.value='';resetPublication();error.value='';message.value='发布已受理，创建排查表后自动发送通知。';}
async function resolvePublication(){const id=pendingPublication.value?.id;if(!id)return false;try{const data=await requestJson(root+'/'+encodeURIComponent(id),{cache:'no-store'});if(data.id!==id)return false;publicationAccepted(data);return true;}catch{return false;}}
async function checkPublication(){if(busy.value||!pendingPublication.value)return;beginWrite();try{if(!await resolvePublication())error.value='尚未核实本次发布。原内容和发布标识已保留，可按原内容重试，请勿重新发布。';}finally{busy.value=false;}}
async function publishNow(){
 if(busy.value)return;
 if(!pendingPublication.value){const issues=publicationIssues(publish,template.value?.fields||[],people.value);if(!template.value||issues.length){error.value='请补充：'+issues.join('；');return;}pendingPublication.value=JSON.parse(JSON.stringify({...publish,template_version:template.value.version}));}
 beginWrite();error.value='';
 try{publicationAccepted(await requestJson(root,{method:'POST',body:JSON.stringify(pendingPublication.value),timeoutMs:60000}));}
 catch(e:any){
  if(e instanceof ApiError&&e.status>=400&&e.status<500&&e.status!==408){pendingPublication.value=null;error.value=e.message;}
  else if(!await resolvePublication()){confirmation.value=null;error.value=e.message+'；发布结果尚未确认，已保留原发布标识。';}
 }finally{busy.value=false;}
}
async function uploadFiles(item:Dict,field:string,files:File[]){if(busy.value||!editable(item))return;error.value='';const invalid=files.find(file=>!file.size||file.size>20*1024*1024||! /\.(pdf|docx?|xlsx?|xlsm|md|txt|csv|jpe?g|png|webp)$/i.test(file.name));if(invalid){error.value=invalid.name+'：请选择20MB以内的非空照片、办公文件或文本文件。';return;}if(((drafts.value[item.id]||item.values)[field]||[]).length+files.length>20){error.value='每个附件字段最多保留20个文件，请先移除不需要的附件。';return;}beginWrite();try{for(const file of files){const q=new URLSearchParams({name:file.name,item_id:item.id,field_id:field});const saved=await requestJson(`${root}/${detail.value!.id}/files?${q}`,{method:'POST',body:file,headers:{'Content-Type':'application/octet-stream'},timeoutMs:120000});item.files.push(saved);const current=drafts.value[item.id]||item.values;drafts.value[item.id]={...current,[field]:[...(current[field]||[]),saved.id]};}}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
async function retry(){if(busy.value||!detail.value)return;beginWrite();error.value='';try{applyDetail(await requestJson(root+'/'+detail.value.id+'/retry',{method:'POST',body:'{}'}));confirmation.value=null;message.value='已安排重试，原操作人和反馈内容保持不变。';}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
function leaving(e:BeforeUnloadEvent){if(unsaved.value||busy.value){e.preventDefault();e.returnValue='';}}
const unregister=registerNavigationGuard((_target,proceed)=>leaveAllowed(proceed));
onMounted(async()=>{await reload();if(disposed)return;const id=props.releaseId||new URLSearchParams(window.location.search).get('id');if(id)await openTask(id,true);if(disposed)return;window.addEventListener('beforeunload',leaving);timer=window.setInterval(()=>{const editing=document.activeElement?.closest('.risk-page input,.risk-page textarea,.risk-feedback input,.risk-feedback textarea,[role="listbox"]');if(!disposed&&!document.hidden&&!busy.value&&!dirty.value&&!editor.value&&!confirmation.value&&!fieldEditor.value&&!editing)void reload();},15000);});
onBeforeUnmount(()=>{disposed=true;read?.abort();unregister();window.clearInterval(timer);window.removeEventListener('beforeunload',leaving);});
</script>
